def match(orders):
    trades = []

    # Resting orders: list of (id, side, price, qty, arrival_time)
    # For buys and sells separately to maintain price-time priority
    buy_book = []  # max heap by price, then min heap by arrival_time
    sell_book = []  # min heap by price, then min heap by arrival_time

    # Track order state: id -> (side, price, qty, arrival_time, is_cancelled)
    order_state = {}

    for arrival_time, order in enumerate(orders):
        if order[0] == 'cancel':
            _, order_id = order
            if order_id in order_state:
                order_state[order_id] = order_state[order_id][:4] + (True,)

        elif order[0] == 'limit':
            _, order_id, side, price, qty = order
            order_state[order_id] = (side, price, qty, arrival_time, False)

            # Try to match
            remaining_qty = qty

            if side == 'buy':
                # Match against sell_book
                matched_sells = []
                for i, (sell_id, sell_side, sell_price, sell_qty, sell_arrival, is_cancelled) in enumerate(sell_book):
                    if is_cancelled or sell_price > price:
                        continue

                    match_qty = min(remaining_qty, sell_qty)
                    trades.append([order_id, sell_id, sell_price, match_qty])

                    remaining_qty -= match_qty
                    sell_qty -= match_qty

                    if sell_qty == 0:
                        matched_sells.append(i)
                    else:
                        sell_book[i] = (sell_id, sell_side, sell_price, sell_qty, sell_arrival, is_cancelled)

